/**
 * Vendored from Watermelon UI registry: https://registry.watermelon.sh/r/button.json
 * Item: button (base kit). Snapshot: UI/_registry/watermelon/r/button.json
 */
import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

/**
 * undo-history-slider — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://axiestudio.github.io/UI_Engine/registry/r/undo-history-slider.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
import * as React from "react"
import { motion, AnimatePresence, MotionConfig } from "motion/react"
import { History, RotateCcw } from "lucide-react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

// ═══ APP-PRIMARY — Figma's history rail, extractable.
// JOB      move through document versions without fear
// SIGNATURE a horizontal scrub rail of version pips; hovering scrubs a GHOST
//           preview (your snapshot render) with a dissolve; releasing commits
//           and a confirm chip springs in with "Restore to 14:22?" — one more
//           click and the timeline itself glides to that point.
// API      versions [{id, at, label, snapshot:ReactNode}], onRestore(id).
// A11Y     slider semantics (value from 0..n-1, home/end), live announce.

export type Version = { id: string; at: string; label: string }
export type UndoHistorySliderProps = { versions: Version[]; head?: string; render: (v: Version) => React.ReactNode; onRestore: (id: string) => void; className?: string }

export function UndoHistorySlider({ versions, head, render, onRestore, className }: UndoHistorySliderProps) {
  const [hoverIdx, setHoverIdx] = React.useState<number | null>(null)
  const [pending, setPending] = React.useState<Version | null>(null)
  const idx = hoverIdx ?? versions.length - 1
  return (
    <div className={cn("relative isolate w-full overflow-hidden rounded-xl border bg-card p-4 font-sans", className)}>
      <MotionConfig reducedMotion="user">
      <div className="relative aspect-[16/9] overflow-hidden rounded-lg border border-border/60 bg-muted/40">
        {versions.map((v, i) => (
          <div key={v.id} aria-hidden={i !== idx} className={cn("absolute inset-0 transition-opacity duration-200", i === idx ? "opacity-100" : "opacity-0")}>{render(v)}      

    </div>
        ))}
        {hoverIdx !== null && hoverIdx < versions.length - 1 && (
          <motion.span initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="absolute right-2 top-2 flex items-center gap-1.5 rounded-full bg-foreground/80 px-2.5 py-1 font-mono text-[10px] font-medium uppercase tracking-wide text-background"><History className="size-3" /> previewing</motion.span>
        )}
      </div>
      <div className="relative mt-5 h-8">
        <span aria-hidden className="absolute left-3 right-3 top-1/2 h-px -translate-y-1/2 bg-border" />
        <div role="slider" tabIndex={0} aria-label="Version history" aria-valuemin={1} aria-valuemax={versions.length} aria-valuenow={idx + 1} aria-valuetext={`${versions[idx]?.label} — ${versions[idx]?.at}`}
          onKeyDown={(e) => { if (e.key === "Home") { setHoverIdx(0); setPending(versions[0]) } if (e.key === "End") { setHoverIdx(null); setPending(null) } if (e.key === "ArrowLeft") { const n = Math.max(0, idx - 1); setHoverIdx(n); setPending(versions[n]) } if (e.key === "ArrowRight") { const n = Math.min(versions.length - 1, idx + 1); n === versions.length - 1 ? (setHoverIdx(null), setPending(null)) : (setHoverIdx(n), setPending(versions[n])) } }}
          className="absolute inset-x-0 top-0 grid h-full place-items-center outline-none">
          <ul className="flex w-full items-center justify-between px-2">
            {versions.map((v, i) => (
              <li key={v.id}>
                <Button type="button" variant="ghost" aria-label={`Preview ${v.label}`} onMouseEnter={() => { setHoverIdx(i); i < versions.length - 1 && setPending(v) }} onMouseLeave={() => hoverIdx !== null && setHoverIdx(null)} className="group grid size-6 place-items-center">
                  <motion.span animate={{ scale: i === idx ? 1.5 : 1, background: i === idx ? "hsl(var(--foreground))" : "hsl(var(--muted-foreground))" }} transition={{ type: "spring", stiffness: 400, damping: 24 }} className="block size-1.5 rounded-full ring-4 ring-card" />
                </Button>
              </li>
            ))}
          </ul>
        </div>
      </div>
      <div className="mt-2 flex items-center justify-between">
        <p className="text-xs text-muted-foreground">{head ?? "history"} · {versions.length} versions</p>
        <AnimatePresence>
          {pending && <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.8, opacity: 0 }}><Button onClick={() => { onRestore(pending.id); setPending(null); setHoverIdx(null) }} className="flex items-center gap-1.5 rounded-full px-3.5 py-1.5 text-xs font-medium shadow-sm"><RotateCcw className="size-3.5" /> restore “{pending.label}”</Button></motion.div>}
        </AnimatePresence>
      </div>
      <p className="sr-only" aria-live="polite">{pending ? `Previewing ${pending.label}. Press restore to apply.` : "At latest version."}</p>
          </MotionConfig>
    </div>
  )
}
